 /// a repeated `initialize_multithreaded()` from a thread-local destructor
 /// during teardown never panics.
 #[cfg(feature = "std")]
 pub fn prepare_thread_scratch() {
-    let _ = SCRATCH_BLOCK.try_with(|_| ());
+    () /* ~ changed by cargo-mutants ~ */
 }

